/**
 * An icon at the size `Ionicons` gives it. In React Native an icon is a text glyph, so [size] scales
 * with the system text size like the words next to it (sp, not dp).
 */
@Composable
internal fun CipherSeamGlyph(icon: CipherSeamIcon, size: Float, color: Color, modifier: Modifier = Modifier) {
    val box = with(LocalDensity.current) { size.sp.toDp() }
    Canvas(modifier.size(box)) {
        scale(this.size.width / 512f, this.size.height / 512f, pivot = Offset.Zero) { drawPath(icon.path, color) }
    }
}
